function heatLoad(x){const inside=psyState(x.tin,'rh',x.rhin,x.pressure*1000),outside=psyState(x.tout,'rh',x.rhout,x.pressure*1000),airflow=x.fresh+x.ach*x.area*x.height,mda=airflow/3600/outside.v;const airS=mda*(1.006+1.86*inside.w)*(outside.t-inside.t)*1000,airT=mda*(outside.h-inside.h)*1000;
const parts=[{key:'walls',s:x.wall*x.uwall*(x.tout-x.tin+x.wallsolar),l:0},{key:'roof',s:x.roof*x.uroof*(x.tout-x.tin+x.roofsolar),l:0},{key:'glass',s:x.glass*x.uglass*(x.tout-x.tin)+x.glass*x.irradiance*x.shgc*x.shade,l:0},{key:'people',s:x.people*x.persons,l:x.people*x.personl},{key:'lights',s:x.area*x.lights,l:0},{key:'equipment',s:x.equipment*x.use,l:0},{key:'air',s:airS,l:airT-airS},{key:'other',s:x.others,l:x.otherl}];const sensible=Math.max(0,parts.reduce((sum,r)=>sum+r.s,0)),latent=Math.max(0,parts.reduce((sum,r)=>sum+r.l,0)),total=sensible+latent,factor=1+x.margin/100,requiredS=sensible*factor,requiredL=latent*factor;const sizes=[9000,12000,18000,24000,30000,36000,48000,60000,72000,96000,120000];const options=sizes.map(btu=>{const capacity=btu/3.412141633*x.units*x.derate;return{btu,capacity,s:capacity*x.acshr,l:capacity*(1-x.acshr),pass:capacity>=total*factor&&capacity*x.acshr>=requiredS&&capacity*(1-x.acshr)>=requiredL};});return{parts,sensible,latent,total,design:total*factor,requiredS,requiredL,shr:total?sensible/total:null,airflow,options,chosen:total>0?options.find(r=>r.pass)||null:null,inside,outside};}
